from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    @lru_cache(None)
    def dp(i):
        if i == n:
            return 0

        ans = a[i]  # Option: delete all a[i] occurrences individually
        h = a[i]
        for j in range(i + 1, n):
            if a[j] >= h:
                h = min(h, a[j])
                ans += sum(a[i:j]) // h + (sum(a[i:j]) % h)
            else:
                ans += a[j]
                break

        return ans

    return str(dp(0))

