        offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = set()
        total_days = 0
        for l, r in offers:
            if r - l + 1 < x:
                continue
            overlap = False
            for d in range(l, r + 1):
                if d in occupied:
                    overlap = True
                    break
            if not overlap:
