        if min(n, m) == 1:
            return '0\n'
        elif min(n, m) == 2:
            # Check if max dimension is large enough
            if max(n, m) < 5:
                return '0\n'
            return '(n*m-1)//2*2\n'
        else:  # min(n, m) == 3
            if max(n, m) < 4:
                return '0\n'
            return str((n * m - 1) // 2 * 2) + '\n'

    # For larger grids
    if total_cells % 2 == 0:
        return str(total_cells) + '\n'
    else:
        return str(total_cells - 1) + '\n'

