def solution(grid_str):
    lines = grid_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    def get_components():
        visited = [[False]*m for _ in range(n)]
        components = []
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and not visited[i][j]:
                    comp = []
                    stack = [(i, j)]
                    visited[i][j] = True
                    while stack:
                        x, y = stack.pop()
                        comp.append((x, y))
                        for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                            nx, ny = x+dx, y+dy
                            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
                    components.append(comp)
        return components

    def is_rectangular(comp):
        r = [x for x, y in comp]
        c = [y for x, y in comp]
        if not r:
            return True
        min_r, max_r = min(r), max(r)
        min_c, max_c = min(c), max(c)
        return len(comp) == (max_r - min_r + 1) * (max_c - min_c + 1)

    while True:
        components = get_components()
        if all(is_rectangular(c) for c in components):
            break
        removed = False
        wall_list = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == '*']
        for i, j in wall_list:
            if not removed:
                grid[i][j] = '.'
                if all(is_rectangular(c) for c in get_components()):
                    removed = True
                else:
                    grid[i][j] = '*'
        if not removed:
            break

    result = '\n'.join(''.join(row) for row in grid) + '\n'
