def nCr(m, r):
    if r < 0 or r > m:
        return 0
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % 1000000007
    inv = [1] * (m + 1)
    for i in range(1, m + 1):
        inv[i] = inv[i - 1] * pow(i, 1000000007 - 2, 1000000007) % 1000000007
    def nCr(m, r):
        return fact[m] * inv[r] * inv[m - r] % 1000000007
    return nCr

