    topo = []
    in_degree = defaultdict(int)
    graph = defaultdict(list)

    all_nodes = set(range(1, n+1))
    for a, b, direction in constraints:
        if direction == "LEFT":
            graph[b].append(a)
            in_degree[a] += 1
        else:
