        for i in range(k):
            val1 = literals[i]
            val2 = literals[(i + 1) % k]

            u = invers(val1)
            v = convert(val2)
            adj[u].append(v)

            u = invers(val2)
            v = convert(val1)
            adj[u].append(v)

    # Kosaraju's algorithm for strongly connected components
    visited = [False] * (2 * m + 1)
