        if not visited[i]:
            dfs1(i)

    # Build reversed graph
    radj = [[] for _ in range(2 * m + 1)]
    for i in range(1, 2 * m + 1):
        for neighbor in adj[i]:
            radj[neighbor].append(i)

    component_id = [0] * (2 * m + 1)
    comp_count = 0
