    # where a_n, b_n, c_n, e_n can be computed using matrix exponentiation

    # We need to track these exponents recursively.
    # Let's set up matrix for (a, b, c, e) transformation

    def mat_mul(A, B, m):
        C = [[0] * m for _ in range(m)]
        for i in range(m):
            for k in range(m):
                if A[i][k]:
                    for j in range(m):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % m
        return C

    def mat_pow(A, p, m):
        result = [[0] * m for _ in range(m)]
        for i in range(m):
            result[i][i] = 1
        while p:
            if p & 1:
                result = mat_mul(result, A, m)
            A = mat_mul(A, A, m)
            p >>= 1
        return result

    # After careful analysis, we can compute the exponents using matrix power:
    # f_n = c^(2*n - 6 + e') * f1^a' * f2^b' * f3^c'
    # where we compute a', b', c', e' efficiently

    # Using exponent tracking matrix
    M = [[2, 2, 2, 0], [1, 2, 2, 0], [1, 1, 2, 0], [0, 0, 0, 1]]
    P = mat_pow(M, n - 3, MOD)

    a = P[0][0] * 1 + P[0][1] * 1 + P[0][2] * 1
    b = P[1][0] * 1 + P[1][1] * 1 + P[1][2] * 1
    c_val = P[2][0] * 1 + P[2][1] * 1 + P[2][2] * 1
    e = P[3][3]
    a = (P[0][0] * 1 + P[0][1] * 1 + P[0][2] * 1) % (MOD - 1)
    b = (P[1][0] * 1 + P[1][1] * 1 + P[1][2] * 1) % (MOD - 1)
    c_val = (P[2][0] * 1 + P[2][1] * 1 + P[2][2] * 1) % (MOD - 1)
    e = (2 * n - 6 + e) % (MOD - 1)

    import functools
    pow_mod = functools.partial(pow, MOD)

    import operator

    from operator import mul

    using_pwr = lambda x, y: pow(x, y, MOD)
    result = (using_pwr(c, e) * using_pwr(f1, a) * using_pwr(f2, b) * using_pwr(f3, c_val)) % MOD
    return str(result)

