memo = {}

def solve(a, k):
    if a == 0:
        return 0
    if a == 1:
        return 1
    if a in memo:
        return memo[a]

    if a % 2 == 1:
        res = solve(a - 1, k)
    else:
        res = solve(a - 1, k)

    # if a is even, we can replace with k piles of size a//2
    if a % 2 == 0:
        half = a // 2
        if k % 2 == 1:
            res = min(res, solve(half, k))

    # compute mex of reachable values
    seen = set()
    if a % 2 == 1:
        val = solve(a - 1, k)
        seen.add(val)
        if a // 2 == a - 1 and k > 0:
            val = solve(a - 1, k)
            seen.add(val)

    if a % 2 == 0:
        half = a // 2
        val1 = solve(half, k)
        if k % 2 == 1:
            seen.add(val1)
        else:
            seen.add(0)

    for x in range(res + 1):
        if x not in seen:
            memo[a] = x
            return x

    return res

