def nCr(n, r, cache):
    if r < 0 or r > n:
        return 0
    if (n, r) in cache:
        return cache[(n, r)]
    if r == 0 or r == n:
        val = 1
    elif r == 1:
        val = n
    else:
        val = nCr(n - 1, r - 1, cache) * n % MOD
    cache[(n, r)] = val
    return val

