        self.cumulative_distance = [0] * n
        cumulative = 0
        for i in range(n):
            cumulative += d[i]
            self.cumulative_distance[i] = cumulative

    def solve(self, n, d, h, queries):
        for i in range(n):
            h[i] = h[i] - d[i]

        def query(a, b):
            if (b - a) % 2 == 1:
                return float('inf')
            mid = (a + b) // 2
            return max(h[i] for i in range(a, b + 1))

        def dist(a, b):
            if a == b:
                return 0
            if a > b:
                return self.cumulative_distance[b] - self.cumulative_distance[a - 1]
            return self.cumulative_distance[b] - self.cumulative_distance[a]

        results = []
        for a, b in queries:
            min_en = float('inf')
            for i in range(a, b + 1):
                for j in range(i + 1, b + 1):
                    en = query(i, j) - dist(i, j)
                    min_en = min(min_en, en)
            results.append(min_en)
        return results

    def solve_all(self, data):
        n, m, d, h, queries = self.parse_input(data)
        self.build_distances(n, d)
        results = self.solve(n, d, h, queries)
        return '\n'.join(map(str, results))

