MOD = 998244353

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    D = int(input_data[0])
    q = int(input_data[1])
    queries = []
    idx = 2
    for _ in range(q):
        v = int(input_data[idx])
        u = int(input_data[idx+1])
        idx += 2
        queries.append((v, u))

    # Factorize D
    prime_factors = {}
    n = D
    p = 2
    while p * p <= n:
        if n % p == 0:
            cnt = 0
            while n % p == 0:
                cnt += 1
                n //= p
            prime_factors[p] = cnt
        p += 1 if p == 2 else 2
    if n > 1:
        prime_factors[n] = 1

    primes = sorted(prime_factors.keys())

    # Compute divisor count for any divisor using prime factorization
    # For a divisor v, we need its exponent for each prime

    # We'll use a memoization approach for queries
    # For each query, we need:
    # 1. Find g = gcd(v, u)
    # 2. Count prime factors of v/g and u/g
    # 3. Number of paths = binomial(|exponents v/g|) * binomial(|exponents u/g|)

    import functools

    @functools.lru_cache(maxsize=None)
    def get_divisor_prime_counts(d):
        counts = {}
        curr = d
        for p in primes:
            if p * p > curr:
                break
            if curr % p == 0:
                cnt = 0
                while curr % p == 0:
                    cnt += 1
                    curr //= p
                counts[p] = cnt
        if curr > 1:
            counts[curr] = counts.get(curr, 0) + 1
        return counts

    @functools.lru_cache(maxsize=None)
    def binom(n, k):
        if k < 0 or k > n:
            return 0
        if k == 0 or k == n:
            return 1
        num = 1
        den = 1
        for i in range(k):
            num = (num * (n - i)) % MOD
            den = (den * (i + 1)) % MOD
        return (num * pow(den, MOD - 2, MOD)) % MOD

    def get_total_exponent(counts):
        return sum(counts.values())

    def count_paths(v, u):
        g = gcd(v, u)
        if v == g:
            return binom(get_total_exponent(get_divisor_prime_counts(u)))
        if u == g:
            # Already handled
            return binom(get_total_exponent(get_divisor_prime_counts(v)))
        v_over_g = v // g
        u_over_g = u // g
        return (binom(get_total_exponent(get_divisor_prime_counts(v_over_g))) * 
                binom(get_total_exponent(get_divisor_prime_counts(u_over_g)))) % MOD

    results = []
    for v, u in queries:
        results.append(str(count_paths(v, u)))

    print('\n'.join(results))

