        for i in range(n):
            for j in range(n):
                if A[i][j] == 0:
                    continue
                for k in range(n):
                    if B[k][j] == 0:
                        continue
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    # Binary exponentiation for matrices
    def mat_pow(A, p):
        if p == 0:
            return [[0] * n for _ in range(n)]
        res = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = A[:]
        while p:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

