    # mat[i][j] = 2^(bit_count(gcd(i+1, j+1)))
    mat = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                mat[i][j] = 1
            else:
                g = math.gcd(i + 1, j + 1)
                mat[i][j] = 1 << bit_count(g)

